<?php
declare(strict_types=1); require_once __DIR__.'/src/auth.php'; require_admin();
$counts=[]; foreach(['students','access_logs','student_history','security_reports','admins'] as $t){$counts[$t]=(int)$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn();}
$logs=$pdo->query("SELECT a.*,s.username FROM access_logs a LEFT JOIN students s ON s.student_id=a.student_id ORDER BY a.login_time DESC LIMIT 8")->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | Dorm Access System</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link href="assets/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/partials/navbar.php';?><div class="container-fluid"><div class="row"><?php include __DIR__.'/partials/sidebar.php';?><main class="col-lg-10 p-4"><h1 class="fw-bold">Dashboard</h1><p class="text-muted">Live data from MySQL database.</p><div class="row g-3 mb-4"><?php foreach([['students','Students','bi-people'],['access_logs','Access Logs','bi-door-open'],['student_history','Student History','bi-clock-history'],['security_reports','Security Reports','bi-exclamation-triangle'],['admins','Admins','bi-person-gear']] as [$k,$label,$icon]):?><div class="col-md-6 col-xl"><div class="card stat-card border-0 shadow-sm h-100"><div class="card-body d-flex justify-content-between"><div><div class="text-muted small"><?=$label?></div><div class="display-6 fw-bold"><?=$counts[$k]?></div></div><div class="stat-icon text-primary"><i class="bi <?=$icon?>"></i></div></div></div></div><?php endforeach;?></div><div class="card border-0 shadow-sm"><div class="card-header bg-white"><h5 class="mb-0">Recent Access Logs</h5></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Log ID</th><th>Student ID</th><th>Username</th><th>Time</th><th>Type</th><th>Status</th><th>Device</th></tr></thead><tbody><?php foreach($logs as $r):?><tr><td><?=h((string)$r['log_id'])?></td><td><?=h((string)($r['student_id']??'NULL'))?></td><td><?=h((string)($r['username']??'Unknown'))?></td><td><?=h($r['login_time'])?></td><td><?=h($r['access_type'])?></td><td><?=h($r['status'])?></td><td><?=h($r['device_id'])?></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="7" class="text-center text-muted py-4">No access logs yet.</td></tr><?php endif;?></tbody></table></div></div></main></div></div></body></html>